/** Idle screen — covers the page after a stretch with no mouse, keyboard or touch, including time spent in another tab, and says when the reader went away. */
export { default as IdleScreen } from './IdleScreen.vue'
export * from './use-idle'

import { onBeforeUnmount, onMounted, ref, toValue, watch, type MaybeRefOrGetter } from 'vue'

// What counts as the reader being there. Moving the mouse counts, so a reader who is only reading still has to nudge it.
const ACTIVITY = ['pointerdown', 'pointermove', 'keydown', 'wheel', 'touchstart', 'scroll'] as const

/**
 * Tracks whether the reader has done nothing for `timeout` ms. Time in another tab or another window
 * counts as nothing, and is caught up on as soon as the page is shown again, since browsers slow
 * timers down in hidden tabs. `idle` goes back to false on the next activity.
 */
export function useIdle(timeout: MaybeRefOrGetter<number>, options: { enabled?: MaybeRefOrGetter<boolean> } = {}) {
  const idle = ref(false)
  /** When the reader last did something, as a timestamp in ms. */
  const lastActive = ref(Date.now())
  let timer: ReturnType<typeof setTimeout> | undefined

  const enabled = () => toValue(options.enabled ?? true)

  function check() {
    clearTimeout(timer)
    if (!enabled()) return
    const left = lastActive.value + toValue(timeout) - Date.now()
    if (left <= 0) idle.value = true
    else timer = setTimeout(check, left)
  }

  /** Start counting again from now, as if the reader had just done something. */
  function reset() {
    lastActive.value = Date.now()
    idle.value = false
    check()
  }

  // Activity only records the time; the one timer re-arms itself, so a moving mouse costs nothing.
  function onActivity() {
    lastActive.value = Date.now()
    if (idle.value) reset()
  }

  // Coming back to the tab is not activity: the reader should see what they missed.
  function onVisibility() {
    if (document.visibilityState === 'visible') check()
  }

  onMounted(() => {
    for (const type of ACTIVITY) window.addEventListener(type, onActivity, { passive: true, capture: true })
    document.addEventListener('visibilitychange', onVisibility)
    reset()
  })

  onBeforeUnmount(() => {
    clearTimeout(timer)
    for (const type of ACTIVITY) window.removeEventListener(type, onActivity, { capture: true })
    document.removeEventListener('visibilitychange', onVisibility)
  })

  // Turning it back on, or changing the timeout, starts the count again.
  watch([enabled, () => toValue(timeout)], () => {
    if (enabled()) return reset()
    clearTimeout(timer)
    idle.value = false
  })

  return { idle, lastActive, reset }
}

export interface CropState {
  /** How far the middle of the picture is from the middle of the frame, in px of the frame. */
  x: number
  y: number
  /** 1 fills the frame exactly; 2 shows the picture at twice that size. */
  zoom: number
}

interface Size {
  width: number
  height: number
}

/** The scale at which the picture just covers the frame, with nothing of the frame left empty. */
export const coverScale = (image: Size, frame: Size) => Math.max(frame.width / image.width, frame.height / image.height)

/** Pulls the picture back so that no edge of it comes inside the frame. */
export function clampOffset(state: CropState, image: Size, frame: Size): CropState {
  const scale = coverScale(image, frame) * state.zoom
  const maxX = Math.max(0, (image.width * scale - frame.width) / 2)
  const maxY = Math.max(0, (image.height * scale - frame.height) / 2)
  return { zoom: state.zoom, x: Math.max(-maxX, Math.min(state.x, maxX)), y: Math.max(-maxY, Math.min(state.y, maxY)) }
}

/** The part of the original picture that is inside the frame, in the picture's own px: what to cut out. */
export function sourceRect(state: CropState, image: Size, frame: Size): { x: number; y: number; width: number; height: number } {
  const scale = coverScale(image, frame) * state.zoom
  const width = frame.width / scale
  const height = frame.height / scale
  return { x: image.width / 2 - state.x / scale - width / 2, y: image.height / 2 - state.y / scale - height / 2, width, height }
}

