/** Password strength — a four-step bar and a word for how strong a password is as it is typed, with a checklist of the rules it must meet. */
export { default as PasswordStrength } from './PasswordStrength.vue'
export { defaultRequirements, scorePassword, type PasswordRequirement, type PasswordScore } from './strength'

/** 0 is nothing typed; 1 weak, 2 fair, 3 good, 4 strong. */
export type PasswordScore = 0 | 1 | 2 | 3 | 4

export interface PasswordRequirement {
  label: string
  test: (password: string) => boolean
}

/** The usual house rules. Pass your own list to match what your server really enforces. */
export const defaultRequirements: readonly PasswordRequirement[] = [
  { label: 'At least 8 characters', test: (password) => password.length >= 8 },
  { label: 'A lower-case and an upper-case letter', test: (password) => /[a-z]/.test(password) && /[A-Z]/.test(password) },
  { label: 'A number or a symbol', test: (password) => /[^A-Za-z\s]/.test(password) },
]

// The ones attackers try first. A password built on one of these is weak however it is dressed up.
const common = ['password', 'passw0rd', '123456', '12345678', 'qwerty', 'letmein', 'welcome', 'admin', 'iloveyou', 'abc123', 'monkey', 'dragon', 'football', '111111']
const runs = ['abcdefghijklmnopqrstuvwxyz', 'qwertyuiop', 'asdfghjkl', 'zxcvbnm', '01234567890']

/**
 * A rough guess at how hard a password is to crack, from its length and how varied it is, marked down for
 * the tricks that add length without adding difficulty. It is a nudge for the person typing, not a check:
 * the real rules belong on your server.
 */
export function scorePassword(password: string): PasswordScore {
  if (!password) return 0
  const lower = password.toLowerCase()

  const kinds = [/[a-z]/, /[A-Z]/, /\d/, /[^A-Za-z\d]/].filter((kind) => kind.test(password)).length
  // Repeated characters count once: "aaaaaaaa" is as easy to guess as "a".
  const distinct = new Set(password).size
  let points = Math.min(password.length, distinct * 2) * (1 + (kinds - 1) * 0.35)

  if (common.some((word) => lower.includes(word))) points *= 0.35
  // Three or more keys in a row from the alphabet, the number line or the keyboard.
  for (const run of runs) {
    for (let start = 0; start + 4 <= run.length; start++) {
      const piece = run.slice(start, start + 4)
      if (lower.includes(piece) || lower.includes([...piece].reverse().join(''))) {
        points *= 0.7
        break
      }
    }
  }

  if (points < 8) return 1
  if (points < 12) return 2
  if (points < 18) return 3
  return 4
}

/** What is typed into the card fields. The number and the dates are digits only, without spaces or slashes. */
export type PaymentCard = {
  name: string
  number: string
  /** Month then year, four digits: 0927. */
  expiry: string
  cvc: string
}

export const emptyCard = (): PaymentCard => ({ name: '', number: '', expiry: '', cvc: '' })

export type CardBrand = 'Visa' | 'Mastercard' | 'American Express' | 'Discover'

/** Which network a card number belongs to, from how it starts. Undefined until enough has been typed to tell, or when it is none of these. */
export function cardBrand(number: string): CardBrand | undefined {
  if (/^4/.test(number)) return 'Visa'
  if (/^3[47]/.test(number)) return 'American Express'
  if (/^(5[1-5]|2(2[2-9]|[3-6]|7[01]|720))/.test(number)) return 'Mastercard'
  if (/^(6011|65|64[4-9])/.test(number)) return 'Discover'
  return undefined
}

/** The checksum every real card number passes. It catches a mistyped or swapped digit; it says nothing about whether the card exists. */
export function passesLuhn(number: string): boolean {
  if (!/^\d{12,19}$/.test(number)) return false
  let sum = 0
  for (let index = 0; index < number.length; index++) {
    let digit = Number(number[number.length - 1 - index])
    if (index % 2 === 1) {
      digit *= 2
      if (digit > 9) digit -= 9
    }
    sum += digit
  }
  return sum % 10 === 0
}

/** Whether "MMYY" is a real month and the card is still good on `today`. A card runs to the end of its month. */
export function expiryState(expiry: string, today = new Date()): 'ok' | 'malformed' | 'expired' {
  if (!/^(0[1-9]|1[0-2])\d\d$/.test(expiry)) return 'malformed'
  const month = Number(expiry.slice(0, 2))
  const year = 2000 + Number(expiry.slice(2))
  const current = today.getFullYear() * 12 + today.getMonth() + 1
  return year * 12 + month < current ? 'expired' : 'ok'
}

