 *
 *   <section v-reveal>…</section>
 *   <li v-for="(item, index) in items" v-reveal="index * 80">…</li>    each a little after the last
 *
 * The value is a delay in milliseconds. Elements already on screen when the page loads are left
 * alone, so nothing above the fold flashes out and back in.
 */
let observer: IntersectionObserver | undefined

function watcher(): IntersectionObserver {
  observer ??= new IntersectionObserver(
    (entries) => {
      for (const entry of entries) {
        if (!entry.isIntersecting) continue
        ;(entry.target as HTMLElement).dataset.reveal = 'shown'
        // Once is enough: it does not hide again when scrolled past.
        observer!.unobserve(entry.target)
      }
    },
    // A little of it has to be showing before it starts, so the movement is actually seen.
    { threshold: 0.15, rootMargin: '0px 0px -5% 0px' },
  )
  return observer
}

export const vReveal: Directive<HTMLElement, number | undefined> = {
  mounted(el, binding) {
    if (typeof IntersectionObserver === 'undefined') return
    const box = el.getBoundingClientRect()
    const onScreen = box.top < window.innerHeight && box.bottom > 0
    if (onScreen) return
    if (binding.value) el.style.setProperty('--er-reveal-delay', `${binding.value}ms`)
    el.dataset.reveal = 'waiting'
    watcher().observe(el)
  },
  unmounted(el) {
    observer?.unobserve(el)
  },
}

/** Reveal — content that fades and slides into place the first time it is scrolled into view, added with v-reveal. */
import './reveal.css'

export { vReveal } from './directive'

@layer components {
  /* Waiting below the fold: invisible and nudged down. The directive only sets this in a browser
     that can run it, so without JavaScript (or on the server) everything is simply visible. */
  [data-reveal='waiting'] {
    opacity: 0;
    transform: translateY(var(--er-reveal-distance, 1rem));
  }

  [data-reveal='shown'] {
    transition:
      opacity 500ms var(--er-ease, ease-out) var(--er-reveal-delay, 0ms),
      transform 500ms var(--er-ease, ease-out) var(--er-reveal-delay, 0ms);
  }

  /* No movement for anyone who has asked for less of it: the content is just there. */
  @media (prefers-reduced-motion: reduce) {
    [data-reveal] {
      opacity: 1;
      transform: none;
      transition: none;
    }
  }
}

/** The only tags the editor keeps. Everything else is unwrapped: its text stays, the tag goes. */
const ALLOWED = new Set(['P', 'BR', 'STRONG', 'B', 'EM', 'I', 'U', 'S', 'DEL', 'STRIKE', 'A', 'UL', 'OL', 'LI', 'H2', 'H3', 'BLOCKQUOTE', 'CODE', 'PRE', 'DIV'])
/** Tags whose contents go too. */
const DROPPED = new Set(['SCRIPT', 'STYLE', 'IFRAME', 'OBJECT', 'EMBED', 'TEMPLATE', 'NOSCRIPT', 'SVG', 'MATH', 'HEAD', 'TITLE', 'META', 'LINK'])

/** An address that is safe to link to. Anything with a scheme other than these, such as javascript:, is refused. */
export function safeHref(href: string): string | undefined {
  const trimmed = href.trim()
  const scheme = trimmed.match(/^([a-z][a-z\d+.-]*):/i)?.[1]!.toLowerCase()
  return trimmed && (!scheme || ['http', 'https', 'mailto', 'tel'].includes(scheme)) ? trimmed : undefined
}

function walk(parent: Node) {
  for (const child of Array.from(parent.childNodes)) {
    if (child.nodeType === Node.TEXT_NODE) continue
    if (child.nodeType !== Node.ELEMENT_NODE) {
      child.remove()
      continue
    }
    const el = child as Element
    const tag = el.tagName.toUpperCase()
    if (DROPPED.has(tag)) {
      el.remove()
      continue
    }
    walk(el)
    if (!ALLOWED.has(tag)) {
      el.replaceWith(...Array.from(el.childNodes))
      continue
    }
    // No attribute survives except a link's address: no styles, no classes, no event handlers.
    for (const attribute of Array.from(el.attributes)) {
      if (!(tag === 'A' && attribute.name === 'href')) el.removeAttribute(attribute.name)
    }
    if (tag === 'A') {
      const href = safeHref(el.getAttribute('href') ?? '')
      if (href) el.setAttribute('rel', 'noopener noreferrer')
      else el.removeAttribute('href')
    }
  }
}

/**
 * Strips HTML down to the formatting the editor offers. Used on what is pasted in and on the value given
 * to the editor. It needs a browser: on a server it returns nothing, and the editor fills in once mounted.
 * Clean the HTML again on your server before storing it; a request can be made without this page.
 */
export function cleanHtml(html: string): string {
  if (typeof DOMParser === 'undefined') return ''
  // Parsed into a document of its own, where scripts do not run and pictures do not load.
  const body = new DOMParser().parseFromString(`<body>${html}</body>`, 'text/html').body
  walk(body)
  return body.innerHTML
}

